function pixelMeasure(s,size=8){return Math.max(0,s.length*6-1)}
function pixelText(context,s,x,y,size=8,color='#e4e6e8',align='left',scale=1){const w=5,h=7,advance=6;context.fillStyle=color;s.toUpperCase().split('\n').forEach((line,lineIndex)=>{let ox=Math.round(x-(align==='center'?(line.length*advance-1)*scale/2:align==='right'?(line.length*advance-1)*scale:0));let oy=Math.round(y+lineIndex*(size===6?8:size+4)*scale);for(const ch of line){const rows=glyphRows[ch]||glyphRows['?'];for(let py=0;py<h;py++)for(let px=0;px<w;px++){if(rows[Math.floor(py*7/h)][Math.floor(px*5/w)]==='1')context.fillRect(ox+px*scale,oy+py*scale,scale,scale)}ox+=advance*scale}})}
// Graphics are rasterized once at their native game size, using a shared 64-colour palette.
const gamePalette=['060c16','0c1420','162033','202e43','304562','45617f','597ca0','79a0be','10223c','15385c','1c507b','276c9b','3889b4','60aaca','8bc4de','bddde8','14221f','203128','304434','445b3c','5b7447','789059','9aad77','c1c99a','171c23','292f37','3e454c','545d63','6d787a','899697','a9b6b6','d0d9d9','211914','35271b','513824','6b4c30','87613d','a27b50','bc9a6c','ddbe8b','291e25','44303a','63424a','805852','a1705c','bc8b70','d8ad8c','f0cfad','251c36','3c2a53','563e6c','73588b','977aa9','bc9aca','dfc3e2','f5e7ef','301c22','592e30','8e3d35','c4533c','e97a4f','edac68','f1d39a','eff3eb'].map(c=>[parseInt(c.slice(0,2),16),parseInt(c.slice(2,4),16),parseInt(c.slice(4,6),16)]);
const paletteCache=new Map();
function nativeAsset(im,crop,w,h){const out=document.createElement('canvas');out.width=w;out.height=h;const c=out.getContext('2d',{willReadFrequently:true});c.imageSmoothingEnabled=false;if(crop)c.drawImage(im,...crop,0,0,w,h);else c.drawImage(im,0,0,w,h);const raster=c.getImageData(0,0,w,h),d=raster.data;for(let i=0;i<d.length;i+=4){const key=((d[i]>>3)<<10)|((d[i+1]>>3)<<5)|(d[i+2]>>3);let best=paletteCache.get(key);if(!best){let distance=Infinity;for(const p of gamePalette){const score=(d[i]-p[0])**2+(d[i+1]-p[1])**2+(d[i+2]-p[2])**2;if(score<distance){distance=score;best=p}}paletteCache.set(key,best)}d[i]=best[0];d[i+1]=best[1];d[i+2]=best[2];d[i+3]=255}c.putImageData(raster,0,0);return out}

function drawGameBorder(context){context.save();context.setTransform(1,0,0,1,0,0);context.globalAlpha=1;context.globalCompositeOperation="source-over";context.fillStyle=window.currentUI?.settings.lineColor||"#91a1ad";context.fillRect(0,0,320,1);context.fillRect(0,239,320,1);context.fillRect(0,1,1,238);context.fillRect(319,1,1,238);context.restore();}
